1	"use client";
2	
3	import * as React from "react";
4	import { Play, Pause } from "lucide-react";
5	import { t } from "@/lib/i18n";
6	import { useToast } from "@/components/ui/Toast";
7	
8	export interface VoicePlayerProps {
9	  name: string;
10	  /** Transcript text shown (the "voice intro" content). */
11	  intro: string;
12	  /** Larger layout with visible transcript (used on the profile screen). */
13	  big?: boolean;
14	  /** Optional signed URL to real audio. When absent, playback is simulated. */
15	  audioUrl?: string | null;
16	}
17	
18	/** Deterministic bar heights — reads as a voice, not random noise. */
19	const BARS = [7, 14, 10, 19, 12, 22, 15, 9, 18, 13, 20, 11, 16, 8, 14, 10];
20	
21	/**
22	 * Decorative waveform. Bars are always visible (the "this is a voice" cue);
23	 * they only move while playing. Static under prefers-reduced-motion via the
24	 * global kill switch.
25	 */
26	function Waveform({ playing, big }: { playing: boolean; big?: boolean }) {
27	  return (
28	    <span
29	      aria-hidden="true"
30	      className={["inline-flex items-center gap-[3px]", big ? "h-7" : "h-[22px]"].join(" ")}
31	    >
32	      {BARS.map((h, i) => (
33	        <span
34	          key={i}
35	          className={[
36	            "w-[3px] rounded-[2px]",
37	            playing ? "bg-accent" : "bg-accent/50",
38	          ].join(" ")}
39	          style={{
40	            height: big ? h * 1.3 : h,
41	            animation: playing
42	              ? `wf 0.9s var(--ease-warm) ${i * 0.07}s infinite alternate`
43	              : undefined,
44	          }}
45	        />
46	      ))}
47	    </span>
48	  );
49	}
50	
51	/**
52	 * Voice-intro player — the signature interaction of the product: you hear a
53	 * person before you see anything about them. Plays real audio when a signed
54	 * URL is provided, otherwise simulates playback. Always shows a transcript on
55	 * the big layout so the content is fully available to screen-reader users.
56	 */
57	export function VoicePlayer({ name, intro, big, audioUrl }: VoicePlayerProps) {
58	  const [playing, setPlaying] = React.useState(false);
59	  const { announce } = useToast();
60	  const audioRef = React.useRef<HTMLAudioElement | null>(null);
61	
62	  const toggle = () => {
63	    const next = !playing;
64	    setPlaying(next);
65	    if (audioUrl && audioRef.current) {
66	      if (next) void audioRef.current.play();
67	      else audioRef.current.pause();
68	    }
69	    announce(
70	      next ? t("ui.announcePlaying", { name }) : t("ui.announcePaused"),
71	    );
72	  };
73	
74	  const diameter = big ? 72 : 52;
75	
76	  return (
77	    <div
78	      className={[
79	        "rounded-tile bg-surface-sunk",
80	        big ? "flex flex-col items-stretch gap-4 p-5" : "flex flex-row items-center gap-3.5 p-3",
81	      ].join(" ")}
82	    >
83	      <div className="flex min-w-0 flex-1 items-center gap-3.5">
84	        <button
85	          type="button"
86	          onClick={toggle}
87	          aria-label={
88	            playing
89	              ? t("ui.pauseVoiceIntro", { name })
90	              : t("ui.playVoiceIntro", { name })
91	          }
92	          aria-pressed={playing}
93	          className={[
94	            "grid flex-none place-items-center rounded-pill bg-primary text-surface shadow-sm",
95	            "transition-[background-color,transform] duration-200 ease-[cubic-bezier(0.33,0.1,0.25,1)]",
96	            "hover:bg-primary-dark active:scale-[0.96] aria-pressed:bg-primary-dark",
97	          ].join(" ")}
98	          style={{ width: diameter, height: diameter }}
99	        >
100	          {playing ? (
101	            <Pause size={big ? 30 : 22} strokeWidth={2} aria-hidden="true" />
102	          ) : (
103	            <Play size={big ? 30 : 22} strokeWidth={2} aria-hidden="true" className="translate-x-[1px]" />
104	          )}
105	        </button>
106	        <div className="flex min-w-0 flex-1 flex-col gap-1">
107	          <span className="truncate text-base font-bold text-ink">
108	            {t("ui.voiceIntroOf", { name })}
109	          </span>
110	          <span className="flex items-center gap-2.5 text-sm text-ink-soft">
111	            <Waveform playing={playing} big={big} />
112	            <span className="whitespace-nowrap">
113	              {playing ? t("ui.playingNow") : t("ui.tapToListen")}
114	            </span>
115	          </span>
116	        </div>
117	      </div>
118	      {big ? (
119	        <p className="border-t border-border pt-4 text-base leading-body text-ink">
120	          <span className="mb-1 block text-xs font-extrabold uppercase tracking-[0.12em] text-ink-soft">
121	            {t("ui.transcript")}
122	          </span>
123	          {intro}
124	        </p>
125	      ) : null}
126	      {audioUrl ? (
127	        <audio
128	          ref={audioRef}
129	          src={audioUrl}
130	          onEnded={() => setPlaying(false)}
131	          className="sr-only"
132	        />
133	      ) : null}
134	    </div>
135	  );
136	}
