5	/**
6	 * Scroll-reveal (fade + rise) via IntersectionObserver — no animation library,
7	 * to keep the JS budget small. Reduced motion: globals.css zeroes
8	 * transition-duration, so content just appears (SPEC §10).
9	 */
10	export function Reveal({
11	  children,
12	  delay = 0,
13	  className = "",
14	}: {
15	  children: React.ReactNode;
16	  delay?: number;
17	  className?: string;
18	}) {
19	  const ref = React.useRef<HTMLDivElement>(null);
20	  const [shown, setShown] = React.useState(false);
21	
22	  React.useEffect(() => {
23	    const el = ref.current;
24	    if (!el) return;
25	    const io = new IntersectionObserver(
26	      ([e]) => {
27	        if (e.isIntersecting) {
28	          setShown(true);
29	          io.disconnect();
30	        }
31	      },
32	      { rootMargin: "0px 0px -10% 0px" },
33	    );
34	    io.observe(el);
35	    return () => io.disconnect();
36	  }, []);
37	
38	  return (
39	    <div
40	      ref={ref}
41	      className={`transition-[opacity,transform] duration-500 ease-[cubic-bezier(0.33,0.1,0.25,1)] ${className}`}
42	      style={{
43	        opacity: shown ? 1 : 0,
44	        transform: shown ? "none" : "translateY(16px)",
45	        transitionDelay: `${delay}ms`,
46	      }}
47	    >
48	      {children}
49	    </div>
50	  );
51	}
