import { Container } from "@/components/shared/Container";
import { Button } from "@/components/ui/Button";
import { t } from "@/lib/i18n";

/**
 * Accessible app-wide error boundary — arc mark, serif statement, one primary
 * path home plus retry (DESIGN_SPEC_V2 §6). Renders inside the root layout,
 * so the persistent safety affordance stays visible. The message is a live
 * region (role="alert") so screen-reader users hear it; recovery is
 * keyboard-operable.
 */
export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  React.useEffect(() => {
    // Surface the error for diagnostics without leaking details to the UI.
    console.error(error);
  }, [error]);

  return (
    <main id="main" className="relative isolate flex-1 overflow-hidden">
      <ArcField className="absolute -right-24 top-1/2 -z-10 h-[560px] w-auto -translate-y-1/2 max-md:hidden" />
      <Container className="flex flex-col items-start gap-6 py-28 max-md:py-16">
        <div role="alert" className="flex flex-col gap-6">
          <h1 className="max-w-2xl text-display max-md:text-h1">
            {t("errors.title")}
          </h1>
          <p className="max-w-xl text-lg leading-body text-ink-soft">
            {t("errors.body")}
          </p>
        </div>
        <div className="flex flex-wrap gap-4 pt-2">
          <Link href="/" className="rounded-pill">
            <Button icon={Home}>{t("errors.home")}</Button>
          </Link>
          <Button variant="ghost" icon={RotateCcw} onClick={() => reset()}>
            {t("errors.retry")}
          </Button>
        </div>
      </Container>
    </main>
  );
}
